    private static func append(_ data: String, to path: inout Path) {
        let scanner = Scanner(string: data)
        scanner.charactersToBeSkipped = nil
        var command: Character?
        var current = CGPoint.zero
        var subpathStart = CGPoint.zero

        while !scanner.isAtEnd {
            if let next = nextCommand(in: scanner) {
                command = next
            }
            guard let command else { return }

            switch command {
            case "M", "m":
                guard let point = nextPoint(in: scanner) else { return }
                current = resolved(point, relative: command == "m", from: current)
                path.move(to: current)
                subpathStart = current
                while let point = nextPoint(in: scanner) {
                    current = resolved(point, relative: command == "m", from: current)
                    path.addLine(to: current)
                }
            case "L", "l":
                while let point = nextPoint(in: scanner) {
                    current = resolved(point, relative: command == "l", from: current)
                    path.addLine(to: current)
                }
            case "H", "h":
                while let value = nextNumber(in: scanner) {
                    current.x = command == "h" ? current.x + value : value
                    path.addLine(to: current)
                }
            case "V", "v":
                while let value = nextNumber(in: scanner) {
                    current.y = command == "v" ? current.y + value : value
                    path.addLine(to: current)
                }
            case "C", "c":
                while let control1 = nextPoint(in: scanner),
                      let control2 = nextPoint(in: scanner),
                      let end = nextPoint(in: scanner) {
                    let relative = command == "c"
                    let resolvedControl1 = resolved(control1, relative: relative, from: current)
                    let resolvedControl2 = resolved(control2, relative: relative, from: current)
                    current = resolved(end, relative: relative, from: current)
                    path.addCurve(to: current, control1: resolvedControl1, control2: resolvedControl2)
                }
            case "Z", "z":
                path.closeSubpath()
                current = subpathStart
            default:
                return
            }
        }
    }

    private static func nextCommand(in scanner: Scanner) -> Character? {
        skipSeparators(in: scanner)
        guard scanner.currentIndex < scanner.string.endIndex else { return nil }
        let character = scanner.string[scanner.currentIndex]
        guard character.isLetter else { return nil }
        scanner.currentIndex = scanner.string.index(after: scanner.currentIndex)
        return character
    }

    private static func nextPoint(in scanner: Scanner) -> CGPoint? {
        guard let x = nextNumber(in: scanner), let y = nextNumber(in: scanner) else { return nil }
        return CGPoint(x: x, y: y)
    }

    private static func nextNumber(in scanner: Scanner) -> CGFloat? {
        skipSeparators(in: scanner)
        guard let value = scanner.scanDouble() else { return nil }
        return value
    }

    private static func skipSeparators(in scanner: Scanner) {
        _ = scanner.scanCharacters(from: CharacterSet(charactersIn: " ,\n\t\r"))
    }

    private static func resolved(_ point: CGPoint, relative: Bool, from current: CGPoint) -> CGPoint {
        relative ? CGPoint(x: current.x + point.x, y: current.y + point.y) : point
    }
}
